begin;
do $$
declare d jsonb;
begin
  for d in select value from jsonb_array_elements($defs$[{"id":"dad93d2a-d4b3-570c-baa1-f509e854a542","key":"mspss","version":"v1","instrumentLocale":"en","translationVersion":"official-en-v1","timeframe":"general","scoringKey":"configured","scoringVersion":"v1","resultVersion":"v1","title":"Social Support Profile","source":{"title":"Multidimensional Scale of Perceived Social Support (MSPSS)","url":"https://gzimet.wixsite.com/mspss","permission":"free-to-use-with-citation","retrievedAt":"2026-10-06","citation":"Zimet GD, Dahlem NW, Zimet SG, Farley GK. Journal of Personality Assessment. 1988;52:30-41."},"answerScale":{"min":1,"max":7},"responseAnchors":["Very strongly disagree","Strongly disagree","Mildly disagree","Neutral","Mildly agree","Strongly agree","Very strongly agree"],"scoring":{"dimensions":[{"key":"resources.mspss.significant_other","method":"mean","items":["mspss.01","mspss.02","mspss.05","mspss.10"],"min":1,"max":7,"dimensionClass":"resources","sourceConstruct":"Significant-other support","direction":"higher-reported-resource"},{"key":"resources.mspss.family","method":"mean","items":["mspss.03","mspss.04","mspss.08","mspss.11"],"min":1,"max":7,"dimensionClass":"resources","sourceConstruct":"Family support","direction":"higher-reported-resource"},{"key":"resources.mspss.friends","method":"mean","items":["mspss.06","mspss.07","mspss.09","mspss.12"],"min":1,"max":7,"dimensionClass":"resources","sourceConstruct":"Friends support","direction":"higher-reported-resource"},{"key":"resources.mspss.overall","method":"mean","items":["mspss.01","mspss.02","mspss.03","mspss.04","mspss.05","mspss.06","mspss.07","mspss.08","mspss.09","mspss.10","mspss.11","mspss.12"],"min":1,"max":7,"dimensionClass":"resources","sourceConstruct":"Overall perceived social support","direction":"higher-reported-resource"}]},"questions":[{"id":"mspss.01","text":"There is a special person who is around when I am in need.","required":true},{"id":"mspss.02","text":"There is a special person with whom I can share joys and sorrows.","required":true},{"id":"mspss.03","text":"My family really tries to help me.","required":true},{"id":"mspss.04","text":"I get the emotional help & support I need from my family.","required":true},{"id":"mspss.05","text":"I have a special person who is a real source of comfort to me.","required":true},{"id":"mspss.06","text":"My friends really try to help me.","required":true},{"id":"mspss.07","text":"I can count on my friends when things go wrong.","required":true},{"id":"mspss.08","text":"I can talk about my problems with my family.","required":true},{"id":"mspss.09","text":"I have friends with whom I can share my joys and sorrows.","required":true},{"id":"mspss.10","text":"There is a special person in my life who cares about my feelings.","required":true},{"id":"mspss.11","text":"My family is willing to help me make decisions.","required":true},{"id":"mspss.12","text":"I can talk about my problems with my friends.","required":true}],"optionalContext":[],"suggestedRepeatDays":30,"contentHash":"sha256:8be799e2ccc49824968be3f56cd9200cd881a2c19276754b4bc7c85c025a8fbc"},{"id":"b3cb9fb1-0626-52c6-a678-fc71b1ae34b3","key":"erq","version":"v1","instrumentLocale":"en","translationVersion":"official-en-v1","timeframe":"general","scoringKey":"configured","scoringVersion":"v1","resultVersion":"v1","title":"Emotion Regulation Style","source":{"title":"Emotion Regulation Questionnaire (ERQ)","url":"https://www.cmu.edu/common-cold-project/measures-by-study/psychological-and-social-constructs/other-psychological-measures/emotion-regulation.html","permission":"public-domain","retrievedAt":"2026-10-06","citation":"Gross JJ, John OP. Journal of Personality and Social Psychology. 2003;85:348-362."},"answerScale":{"min":1,"max":7},"responseAnchors":["Strongly disagree","Disagree","Slightly disagree","Neutral","Slightly agree","Agree","Strongly agree"],"scoring":{"dimensions":[{"key":"resources.erq.reappraisal","method":"mean","items":["erq.01","erq.03","erq.05","erq.07","erq.08","erq.10"],"min":1,"max":7,"dimensionClass":"resources","sourceConstruct":"Cognitive reappraisal","direction":"non-normative"},{"key":"resources.erq.suppression","method":"mean","items":["erq.02","erq.04","erq.06","erq.09"],"min":1,"max":7,"dimensionClass":"resources","sourceConstruct":"Expressive suppression","direction":"non-normative"}]},"questions":[{"id":"erq.01","text":"When I want to feel more positive emotion (such as joy or amusement), I change what I’m thinking about.","required":true},{"id":"erq.02","text":"I keep my emotions to myself.","required":true},{"id":"erq.03","text":"When I want to feel less negative emotion (such as sadness or anger), I change what I’m thinking about.","required":true},{"id":"erq.04","text":"When I am feeling positive emotions, I am careful not to express them.","required":true},{"id":"erq.05","text":"When I’m faced with a stressful situation, I make myself think about it in a way that helps me stay calm.","required":true},{"id":"erq.06","text":"I control my emotions by not expressing them.","required":true},{"id":"erq.07","text":"When I want to feel more positive emotion, I change the way I’m thinking about the situation.","required":true},{"id":"erq.08","text":"I control my emotions by changing the way I think about the situation I’m in.","required":true},{"id":"erq.09","text":"When I am feeling negative emotions, I make sure not to express them.","required":true},{"id":"erq.10","text":"When I want to feel less negative emotion, I change the way I’m thinking about the situation.","required":true}],"optionalContext":[],"suggestedRepeatDays":60,"contentHash":"sha256:86b3c6a2fc11462c66620b6835de10fc8beac4f568d756c7783b0fcdb6609181"},{"id":"20f3b56b-262e-5712-a0e3-62c365aab031","key":"phq-15","version":"v1","instrumentLocale":"en","translationVersion":"official-en-v1","timeframe":"past-4-weeks","scoringKey":"configured","scoringVersion":"v1","resultVersion":"v1","title":"Body Symptom Profile","source":{"title":"Patient Health Questionnaire-15 (PHQ-15)","url":"https://nda.nih.gov/data-structure/phq01","permission":"phq-family-no-permission-required","retrievedAt":"2026-10-06"},"answerScale":{"min":0,"max":2},"responseAnchors":["Not bothered at all","Bothered a little","Bothered a lot"],"scoring":{"dimensions":[{"key":"symptoms.phq15.total","method":"sum","items":["phq15.01","phq15.02","phq15.03","phq15.04","phq15.05","phq15.06","phq15.07","phq15.08","phq15.09","phq15.10","phq15.11","phq15.12","phq15.13","phq15.14","phq15.15"],"min":0,"max":30,"dimensionClass":"symptoms","sourceConstruct":"Physical symptom burden","direction":"lower-reported-difficulty"}]},"questions":[{"id":"phq15.01","text":"Stomach pain","required":true},{"id":"phq15.02","text":"Back pain","required":true},{"id":"phq15.03","text":"Pain in your arms, legs, or joints (knees, hips, etc.)","required":true},{"id":"phq15.04","text":"Menstrual cramps or other problems with your periods (if applicable)","required":true},{"id":"phq15.05","text":"Headaches","required":true},{"id":"phq15.06","text":"Chest pain","required":true},{"id":"phq15.07","text":"Dizziness","required":true},{"id":"phq15.08","text":"Fainting spells","required":true},{"id":"phq15.09","text":"Feeling your heart pound or race","required":true},{"id":"phq15.10","text":"Shortness of breath","required":true},{"id":"phq15.11","text":"Pain or problems during sexual intercourse","required":true},{"id":"phq15.12","text":"Constipation, loose bowels, or diarrhea","required":true},{"id":"phq15.13","text":"Nausea, gas, or indigestion","required":true},{"id":"phq15.14","text":"Feeling tired or having low energy","required":true},{"id":"phq15.15","text":"Trouble sleeping","required":true}],"optionalContext":[],"suggestedRepeatDays":30,"contentHash":"sha256:6f1a2bbd823baffceebc8016985fa13f823686440b1b6433a16a58de38a4b4bf"},{"id":"f6a8cc1b-7f05-5034-985c-139e4b91fb64","key":"brcs","version":"v1","instrumentLocale":"en","translationVersion":"official-en-v1","timeframe":"general","scoringKey":"configured","scoringVersion":"v1","resultVersion":"v1","title":"Resilient Coping","source":{"title":"Brief Resilient Coping Scale (BRCS)","url":"https://doi.org/10.1177/1073191103258144","permission":"public-domain","retrievedAt":"2026-10-06","citation":"Sinclair VG, Wallston KA. Assessment. 2004;11(1):94-101."},"answerScale":{"min":1,"max":5},"responseAnchors":["Does not describe me at all","Does not describe me","Neutral","Describes me","Describes me very well"],"scoring":{"dimensions":[{"key":"resources.brcs.total","method":"sum","items":["brcs.01","brcs.02","brcs.03","brcs.04"],"min":4,"max":20,"dimensionClass":"resources","sourceConstruct":"Resilient coping","direction":"higher-reported-resource"}]},"questions":[{"id":"brcs.01","text":"I look for creative ways to alter difficult situations.","required":true},{"id":"brcs.02","text":"Regardless of what happens to me, I believe I can control my reaction to it.","required":true},{"id":"brcs.03","text":"I believe that I can grow in positive ways by dealing with difficult situations.","required":true},{"id":"brcs.04","text":"I actively look for ways to replace the losses I encounter in life.","required":true}],"optionalContext":[],"suggestedRepeatDays":30,"contentHash":"sha256:36909454f6d0151efeb26e7e253194548dc1683e2db579f68ba1b186a7739a44"}]$defs$::jsonb)
  loop
    if exists (
      select 1 from app.assessment_versions
      where id=(d->>'id')::uuid and content_hash<>d->>'contentHash'
    ) then
      raise exception 'Published assessment definition % differs from reviewed definition', d->>'id';
    end if;
    insert into app.assessment_versions(
      id,definition_key,definition_version,instrument_locale,translation_version,
      definition,questions,answer_schema,scoring_key,scoring_version,result_schema,
      timeframe,source_metadata,content_hash
    ) values (
      (d->>'id')::uuid,d->>'key',d->>'version',d->>'instrumentLocale',d->>'translationVersion',
      d,d->'questions',
      jsonb_build_object('type','integer','minimum',(d->'answerScale'->>'min')::int,'maximum',(d->'answerScale'->>'max')::int),
      d->>'scoringKey',d->>'scoringVersion',jsonb_build_object('version',d->>'resultVersion'),
      d->>'timeframe',d->'source',d->>'contentHash'
    ) on conflict(id) do nothing;
  end loop;
end $$;
